using System;using System.IO;using System.Linq;using System.Text;using System.Xml;using System.Globalization;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class OpeningItem {
 public string Id,Description,Wall,Material,Kind;public double Width,Height,JambDepth,JambThickness,LeafThickness;public int Quantity,Faces,HingesPerUnit,LocksPerUnit;public int Leaves=1;public string Operation="Swing";public bool Exterior;public string MouldingProfile="";/* units of this opening that get moulding (owner, 23 November 2026: "editable quantity kasi di naman lahat malalagyan"); -1 = all */public int MouldingQuantity=-1;
 /* Owner (17 November 2026): painting of the door/window leaf and of the jamb can each be left out. */public bool PaintLeaf=true,PaintJamb=true;
 public double MouldingLength{get{return Material=="Manual"||Material=="Opening"||MouldingQuantity==0?0:OpeningMoulding.Length(Kind,Width,Height,MouldingQuantity>=0?MouldingQuantity:Quantity,Exterior);}}
 public double Area{get{return Width*Height*Quantity;}}
 public bool Wood{get{return Material=="Wood";}}
 public double LeafWidth{get{return Width-2*JambThickness;}}public double LeafHeight{get{return Height-(Kind=="Window"?2:1)*JambThickness;}}
 public double EffectiveThickness{get{return Wood&&Kind=="Door"?OpeningHardware.WoodDoorThickness:LeafThickness;}}
 public double LeafPaint{get{return Wood&&PaintLeaf?(Faces*LeafWidth*LeafHeight+2*(LeafWidth+LeafHeight*(Kind=="Door"?Leaves:1))*EffectiveThickness)*Quantity:0;}}
 /* owner, 20 November 2026 ("magkaiba talaga ang jamb depth ... based sa thk ng masonry wall"): one opening ID in walls of
    different thickness - each group of units uses the jamb depth of its own wall (depth m, units); null = JambDepth for all */
 public List<KeyValuePair<double,int>> JambGroups;
 public double JambPaint{get{if(!(Wood&&PaintJamb))return 0;double perimeter=2*Height+Width+(Kind=="Window"?Width:0);if(JambGroups!=null&&JambGroups.Count>0)return JambGroups.Sum(g=>perimeter*(g.Key+2*JambThickness)*g.Value);return perimeter*(JambDepth+2*JambThickness)*Quantity;}}
 /* owner, 20 November 2026: "no locket hinges if aluminum" - aluminum doors and windows come with their own hardware */public bool NoHardware{get{return Material=="Aluminum";}}
 public int EffectiveHinges{get{if(Material=="Manual"||Material=="Opening"||NoHardware||Operation=="Fixed"||Operation=="Sliding")return 0;if(Kind=="Door")return checked(DoorLeaves().Sum(w=>OpeningHardware.PerLeaf(Wood?LeafHeight:Height,w)));return HingesPerUnit;}}
 public int EffectiveLocks{get{if(Material=="Manual"||Material=="Opening"||NoHardware||Operation=="Fixed")return 0;return Kind=="Door"?1:LocksPerUnit;}}
 public int Hinges{get{return checked(EffectiveHinges*Quantity);}}public int Locks{get{return checked(EffectiveLocks*Quantity);}}
 public void Validate(){if(string.IsNullOrWhiteSpace(Id)||(string.IsNullOrWhiteSpace(Description)&&Material!="Opening")||(Material=="Manual"&&string.IsNullOrWhiteSpace(Wall)))throw new Exception("Enter Opening ID and description; manual CHB openings also require Wall ID.");/* a plain Opening needs no description (owner, 18 November 2026) */if(Material!="Wood"&&Material!="Aluminum"&&Material!="PVC"&&Material!="Steel"&&Material!="Opening"&&Material!="Manual")throw new Exception("Select Wood, Aluminum, PVC or Steel.");if(Leaves<1||Leaves>8)throw new Exception("Door leaves/unit must be between 1 and 8.");if(Operation!="Swing"&&Operation!="Sliding"&&Operation!="Fixed")throw new Exception("Select Swing, Sliding or Fixed operation.");if(Kind!="Door"&&Kind!="Window"&&Kind!="Opening")throw new Exception("Select Door, Window or Opening.");foreach(double v in new[]{Width,Height,JambDepth,JambThickness,LeafThickness})if(double.IsNaN(v)||double.IsInfinity(v)||v<0||v>10000)throw new Exception("Check opening dimensions.");if(Width<=0||Height<=0||Quantity<1||Quantity>100000||Faces<0||Faces>2||HingesPerUnit<0||HingesPerUnit>100||LocksPerUnit<0||LocksPerUnit>100)throw new Exception("Check dimensions, quantity, faces and hardware counts.");if(Wood&&(JambDepth<=0||JambThickness<=0||LeafThickness<=0||LeafWidth<=0||LeafHeight<=0))throw new Exception("Enter wooden leaf and jamb dimensions.");}
}
class WallItem {public string Id,Description;public string Material="CHB";public string Plaster="2 sides",Paint="Same as plaster";public double ThicknessMm=150;public double Length,Height,BlockWidth,BlockHeight;public int Quantity;
 public double? EnteredArea; /* gross area input x Wall Qty (owner, 18 November 2026: "kapag area ang ginamit ko", changing Qty did not change the total) */public double Gross{get{return EnteredArea.HasValue?EnteredArea.Value*Quantity:Length*Height*Quantity;}}
 public void Validate(){if(string.IsNullOrWhiteSpace(Id)||string.IsNullOrWhiteSpace(Description))throw new Exception("Enter Wall ID and description.");if(EnteredArea.HasValue&&(double.IsNaN(EnteredArea.Value)||double.IsInfinity(EnteredArea.Value)||EnteredArea.Value<=0))throw new Exception("Enter a positive gross wall area in m2, before opening deductions.");foreach(double v in (EnteredArea.HasValue?new[]{BlockWidth,BlockHeight}:new[]{Length,Height,BlockWidth,BlockHeight}))if(double.IsNaN(v)||double.IsInfinity(v)||v<=0||v>10000)throw new Exception("Wall/block dimensions must be positive.");if(double.IsNaN(ThicknessMm)||double.IsInfinity(ThicknessMm)||(ThicknessMm!=100&&ThicknessMm!=150))throw new Exception("Select CHB thickness: 100 or 150 mm.");if(Quantity<1||Quantity>100000)throw new Exception("Enter a positive whole wall quantity.");}
 public double Deduction(IEnumerable<OpeningItem> openings){return openings.Where(o=>string.Equals(o.Wall.Trim(),Id.Trim(),StringComparison.OrdinalIgnoreCase)).Sum(o=>o.Area);}
 public double Net(IEnumerable<OpeningItem> openings){Validate();if(openings.Count(o=>string.Equals(o.Wall.Trim(),Id.Trim(),StringComparison.OrdinalIgnoreCase))>3)throw new Exception("Maximum 3 opening entries per wall group (linked + manual); each entry can have multiple units.");double result=Gross-Deduction(openings);if(result< -0.0000001)throw new Exception("Openings exceed gross wall area. Check dimensions and total opening quantities.");return Math.Max(0,result);}
 public long Blocks(IEnumerable<OpeningItem> openings){return checked((long)Math.Ceiling(Math.Round(Net(openings)/(BlockWidth*BlockHeight),10)));}
}

}


